# ======================= AAQ: 토큰 보상과 숙제 완성(실험) =======================
def psf_aaq_token_homework(rng):
    intro = _article("Token Rewards and Homework Completion in Fifth Graders", [
        ("Introduction", "Teachers want students to finish their homework regularly. Behavioral research suggests that reinforcing a behavior makes it more likely to occur. In this study, researchers tested the hypothesis that fifth graders who earn tokens for completing homework will complete a greater percentage of their homework than fifth graders who earn no tokens."),
        ("Participants", "The 100 participants were fifth graders from four classrooms in one public elementary school. All students whose parents returned a permission form and who agreed to take part were included. A computer randomly assigned the students to the Token group (50 students) or the No-token group (50 students)."),
        ("Procedure", "For six weeks, teachers assigned the same daily homework to all students. In the Token group, a student earned one token for each assignment that was handed in complete, and ten tokens could be exchanged for a classroom privilege. Students in the No-token group received no tokens. Homework completion was defined as the percentage of the assigned homework handed in complete during the six weeks."),
        ("Ethical procedures", "The school district's institutional review board approved the study. Parents gave written permission, and each student agreed and was told that he or she could stop at any time without penalty. At the end of the study, the No-token group was also offered the token program. Students' records were identified only by code numbers."),
        ("Results", "The table shows the results. The researchers reported that the difference between the groups was statistically significant."),
    ])
    stim = tbl("Percentage of assigned homework handed in complete over six weeks", ["Group", "Number of students", "Mean homework completion (percent)", "Standard deviation"], [["Token", "50", "82", "11"], ["No-token", "50", "64", "13"]])
    a = ("Identify the research method used in the study.", "The research method is an experiment: the researchers manipulated whether students could earn tokens and randomly assigned students to the two groups.",
         [fr("A1", 1, "Identifies the research method as an experiment", ["Identifies the research method as an experiment (accept references to manipulating the token reward with random assignment)"], ["an experimental design with a token group and a no-token group", "experiment because students were randomly assigned to conditions"], ["correlational study", "case study", "naturalistic observation", "survey"])])
    b = ("State the operational definition of homework completion.", "Homework completion was defined as the percentage of the assigned homework that was handed in complete during the six weeks.",
         [fr("B1", 1, "States the measurable definition of homework completion as used in the study", ["States that homework completion is the percentage of assigned homework handed in complete over the six weeks"], ["the percent of assignments that students handed in complete", "the percentage of the assigned homework turned in complete during six weeks"], ["how hard students worked", "whether students did their homework", "the number of tokens earned"])])
    c = ("Describe what the difference in means indicates about homework completion for the Token group compared with the No-token group.", "The Token group's mean of 82 percent is 18 percentage points higher than the No-token group's mean of 64 percent, which indicates that on average the students who could earn tokens completed more of their homework.",
         [fr("C1", 1, "Describes the difference in means in relation to the study", ["States that the Token group completed more homework (on average) than the No-token group, referring to the means or to the difference of 18 percentage points"], ["students who earned tokens handed in more of their homework on average", "the token group completed a higher percentage of their assignments"], ["restates the two means without saying what the difference indicates", "the means are different", "defines the mean as the average"])])
    d = ("Identify one ethical guideline described in the study. Describe one way the researchers applied this ethical guideline.", "Voluntary participation and the right to withdraw: students were told that they could stop at any time without penalty. (Confidentiality: records were identified by code numbers. Informed consent: parents gave written permission. Fair treatment: the No-token group was offered the program afterward.)",
         [fr("D1", 1, "Identifies an ethical guideline described in the study and describes how it was applied", ["Identifies one ethical guideline that is described in the study (informed consent or assent, voluntary participation and the right to withdraw, confidentiality, or institutional review) AND describes the way the researchers applied it"], ["confidentiality: students' records were labeled with code numbers", "right to withdraw: students were told they could stop at any time without penalty", "informed consent: parents gave written permission"], ["names a guideline that the study does not describe, such as deception", "names the guideline without describing how it was applied"])])
    e = ("Explain the extent to which the research findings may or may not be generalizable, using specific and relevant evidence from the study.", "The findings may be generalizable only to a limited extent. The participants were fifth graders from four classrooms in one public elementary school and were students whose parents returned permission forms, so the results may not apply to other grades, other schools, or other regions.",
         [fr("E1", 1, "Explains the extent of generalizability using participant evidence from the study", ["Makes a claim about generalizability to a population AND supports it with specific evidence about the participants, such as their grade, school, number of classrooms, or volunteer status"], ["the sample was fifth graders from one public school, so findings may not apply to high school students or to other districts", "only students with parental permission were included, so the sample may not represent all fifth graders"], ["says the sample size of 100 is too small without using participant variables", "uses reliability or validity as the evidence"], both=True)])
    f = ("Explain how at least one of the research findings supports or refutes the researchers' hypothesis that fifth graders who earn tokens for completing homework will complete a greater percentage of their homework than fifth graders who earn no tokens.", "The finding supports the hypothesis. The Token group's mean completion (82 percent) was higher than the No-token group's (64 percent), and the difference was statistically significant, so it is unlikely to be due to chance, which is consistent with the prediction.",
         [fr("F1", 1, "States whether the results support or refute the hypothesis", ["States that the results support the hypothesis"], ["the findings are consistent with the hypothesis", "the results back up the claim that tokens increase completion"], ["says the results refute the hypothesis", "says the results prove the hypothesis"]),
          fr("F2", 1, "Explains how using specific evidence from the study", ["Uses specific evidence (the higher mean for the Token group, the 18-point difference, or the statistically significant difference) to explain how the finding supports the hypothesis"], ["the token group's mean of 82 percent was higher than 64 percent, as predicted", "because the difference is statistically significant, chance is an unlikely explanation"], ["restates the hypothesis without using evidence", "uses evidence not in the study"], requires="F1")])
    return _mk_frq("psf_aaq_token_homework", "aaq", "3.8", ["3.8", "2.D"], "2.A", "Token rewards and homework completion", intro, stim, _aaq_parts(a, b, c, d, e, f, ["3.8"]), 25,
                   "Article Analysis Question on an experiment: method, operational definition, mean difference, ethics, generalizability, support for the hypothesis", ["Identify the design from the manipulation and random assignment", "Read the operational definition and the mean difference from the text and table", "Use participant evidence to judge generalizability and the results to evaluate the hypothesis"],
                   [("the article states the method, the measure, the means and the ethical procedures", "article text and table")], PATH_FRQ)


# ======================= AAQ: 사회적 지지와 스트레스(상관) =======================
def psf_aaq_support_stress(rng):
    intro = _article("Social Support and Perceived Stress in First-Year College Students", [
        ("Introduction", "The first year of college can be stressful. Health psychologists have proposed that people who feel supported by others cope better with stress. This study tested the hypothesis that first-year students who report more social support report less perceived stress."),
        ("Participants", "The 150 participants were first-year students at one university. The researchers emailed a link to the survey to 900 first-year students, and the 150 students who completed it were included in the study."),
        ("Procedure", "Each student completed an online survey once, in the middle of the fall semester. Social support was defined as the student's total score on a 10-item questionnaire about how much help and encouragement the student receives from friends and family (scores from 10 to 50). Perceived stress was defined as the student's total score on a 10-item questionnaire about how overwhelmed the student felt during the past month (scores from 10 to 50)."),
        ("Ethical procedures", "A university institutional review board approved the study. Students read a consent statement before beginning the survey and could close the survey at any time. Survey answers were stored under code numbers, and the researchers did not collect students' names."),
        ("Results", "The researchers calculated a correlation coefficient between social support scores and perceived stress scores. The table shows the results."),
    ])
    stim = tbl("Results for 150 first-year students", ["Measure", "Mean", "Standard deviation"], [["Social support score (10-50)", "37", "7"], ["Perceived stress score (10-50)", "28", "8"], ["Correlation between social support and perceived stress (r)", "-0.46", "not applicable"]])
    a = ("Identify the research method used in the study.", "The research method is a correlational study (a survey-based correlation): the researchers measured social support and perceived stress and calculated their relationship without manipulating either variable.",
         [fr("A1", 1, "Identifies the research method as correlational", ["Identifies the research method as a correlational study (accept a survey design that measures two variables and calculates their relationship without manipulation)"], ["correlational research", "the study correlated social support with perceived stress"], ["experiment", "case study", "naturalistic observation", "survey only without mentioning a relationship between variables"])])
    b = ("State the operational definition of perceived stress.", "Perceived stress was defined as the student's total score on a 10-item questionnaire about how overwhelmed the student felt during the past month.",
         [fr("B1", 1, "States the measurable definition of perceived stress as used in the study", ["States that perceived stress is the total score on the 10-item questionnaire about how overwhelmed the student felt in the past month"], ["the score on a 10-item questionnaire about feeling overwhelmed", "total score from 10 to 50 on the stress questionnaire"], ["how stressed students feel", "the amount of stress in a student's life", "the support score"])])
    c = ("Describe what the correlation coefficient indicates about the relationship between social support and perceived stress.", "The correlation of -0.46 is negative and moderate, which indicates that students with higher social support scores tended to have lower perceived stress scores.",
         [fr("C1", 1, "Describes the correlation in relation to the study", ["States that the correlation is negative (as support increases stress tends to decrease) and refers to -0.46 or to a moderate relationship"], ["students with more social support tended to report less stress", "the negative correlation means higher support went with lower stress"], ["says the correlation is positive", "says that social support causes stress to decrease", "restates -0.46 without interpreting it"])])
    d = ("Identify one ethical guideline described in the study. Describe one way the researchers applied this ethical guideline.", "Informed consent and voluntary participation: students read a consent statement before the survey and could close the survey at any time. (Confidentiality: answers were stored under code numbers and names were not collected. IRB review: a university board approved the study.)",
         [fr("D1", 1, "Identifies an ethical guideline described in the study and describes how it was applied", ["Identifies one ethical guideline that is described in the study (informed consent, voluntary participation and the right to withdraw, confidentiality or anonymity, or institutional review) AND describes the way the researchers applied it"], ["confidentiality: answers were stored under code numbers and no names were collected", "informed consent: students read a consent statement before taking the survey", "right to withdraw: students could close the survey at any time"], ["names a guideline that the study does not describe, such as debriefing", "names the guideline without describing how it was applied"])])
    e = ("Explain the extent to which the research findings may or may not be generalizable, using specific and relevant evidence from the study.", "The findings may be generalizable only to a limited extent. The participants were first-year students at one university who chose to complete the survey (150 of 900 invited), so the results may not apply to older students, students at other colleges, or students who did not respond.",
         [fr("E1", 1, "Explains the extent of generalizability using participant evidence from the study", ["Makes a claim about generalizability to a population AND supports it with specific evidence about the participants, such as first-year status, one university, or the response of 150 of 900 invited students"], ["participants were first-year students at one university, so findings may not apply to other years or colleges", "only 150 of 900 invited students responded, so the respondents may differ from nonrespondents"], ["says the sample is too small without using participant variables", "uses reliability or validity as the evidence"], both=True)])
    f = ("Explain how at least one of the research findings supports or refutes the researchers' hypothesis that first-year students who report more social support report less perceived stress.", "The finding supports the hypothesis. The correlation of -0.46 is negative, which means students who reported more social support tended to report less perceived stress, as predicted. The correlation does not show that support causes lower stress.",
         [fr("F1", 1, "States whether the results support or refute the hypothesis", ["States that the results support the hypothesis"], ["the findings are consistent with the hypothesis", "the results match the predicted negative relationship"], ["says the results refute the hypothesis", "says the results prove that support causes less stress"]),
          fr("F2", 1, "Explains how using specific evidence from the study", ["Uses specific evidence (the correlation of -0.46 or its negative direction) to explain how the finding supports the hypothesis"], ["the negative correlation of -0.46 shows more support goes with less stress, as predicted", "as support scores rose, stress scores tended to fall"], ["restates the hypothesis without using evidence", "uses evidence not in the study"], requires="F1")])
    return _mk_frq("psf_aaq_support_stress", "aaq", "5.1", ["5.1", "2.C"], "2.A", "Social support and perceived stress", intro, stim, _aaq_parts(a, b, c, d, e, f, ["5.1"]), 25,
                   "Article Analysis Question on a correlational study: method, operational definition, correlation, ethics, generalizability, support for the hypothesis", ["Identify the design from the measurement of two variables without manipulation", "Read the operational definition and interpret the correlation coefficient", "Use participant evidence to judge generalizability and the correlation to evaluate the hypothesis"],
                   [("the article states the method, the measures, the correlation and the ethical procedures", "article text and table")], PATH_FRQ)


# ---- EBQ: 늦은 등교 시간 ----
def psf_ebq_school_start(rng):
    q = "Should a school district move the start of the school day later for high school students?"
    intro = _sources([
        ("A laboratory experiment on sleep and attention", "Researchers randomly assigned 60 high school students to spend either six hours or eight hours in bed for three nights. On the fourth morning, all students completed a 30-minute attention task in which they pressed a key when a target appeared among distractors. The mean accuracy was 71 percent for the six-hour group (30 students) and 85 percent for the eight-hour group (30 students). The difference was statistically significant."),
        ("A survey of students in two districts", "Researchers surveyed 1,200 high school students about their sleep. Students in the district whose school day began at 7:15 a.m. (600 students) reported an average of 6.4 hours of sleep on school nights. Students in the district whose school day began at 8:45 a.m. (600 students) reported an average of 7.6 hours. The researchers noted that the districts were not assigned to start times and may differ in other ways, such as family income."),
        ("A comparison of grades before and after a schedule change", "Researchers followed one school that moved its start time from 7:15 a.m. to 8:45 a.m. The mean grade-point average of the students was 2.90 in the year before the change and 3.02 in the year after. The researchers reported that the difference was not statistically significant (p = .18) and noted that the school also changed some course offerings in the same year."),
    ])
    stim = tbl("Summary of the key results in the three sources", ["Source", "Type of study", "Key result"], [["1", "Experiment (60 students)", "Mean attention accuracy: 71% (six hours in bed) vs 85% (eight hours in bed); statistically significant"], ["2", "Survey (1,200 students in two districts)", "Average sleep on school nights: 6.4 hours (7:15 start) vs 7.6 hours (8:45 start)"], ["3", "Before-and-after comparison at one school", "Mean GPA 2.90 before vs 3.02 after; not statistically significant; course offerings also changed"]])
    claim = ["A district should start the high school day later, because the evidence shows that more sleep improves students' attention and later starts are linked to more sleep.", "High schools should move to a later start time, because students who sleep more perform better on attention tasks.", "A district should consider a later start for high school students, because later starts are linked to more sleep even though the evidence that grades improve is weak."]
    b = ("Source 1: students who spent eight hours in bed had a mean accuracy of 85 percent on the attention task, compared with 71 percent for students who spent six hours in bed.",
         [_ev("B1", "Uses one specific, accurate, and correctly cited piece of evidence from one source", ["Cites one source (Source 1, 2, or 3) and gives specific and relevant evidence from it that supports the student's claim, such as a number or finding"], ["Source 1: 85% versus 71% accuracy", "Source 2: 7.6 hours versus 6.4 hours of sleep", "Source 3: mean GPA rose from 2.90 to 3.02"], ["gives evidence with no citation", "gives a vague statement such as 'the sources say sleep matters'", "gives evidence that is not relevant to the claim"])])
    c = ("Sleep loss impairs attention: when students sleep less, they have more difficulty focusing on a task (selective attention) and filtering out distractors, which explains why the six-hour group was less accurate.",
         _expl_rows("C", ["Applies a psychological perspective, theory, concept, or research finding from the course, such as selective attention, the effects of sleep deprivation on attention, encoding, or memory consolidation during sleep, to explain how the evidence supports the claim"], ["selective attention was reduced by sleep loss", "sleep loss impairs attention, so the sleep-deprived group made more errors", "memory consolidation during sleep: less sleep means less consolidation"], ["explains how the evidence supports the claim: students with more sleep performed better, which supports a later start that allows more sleep", "links the evidence to the claim by showing how the amount of sleep changes performance"], ["students who slept more performed better, which supports giving students more time to sleep", "the difference in attention shows that sleep amount changes performance, so the claim is supported"]))
    d = ("Source 2: students in the district with an 8:45 a.m. start reported an average of 7.6 hours of sleep on school nights, compared with 6.4 hours in the district with a 7:15 a.m. start.",
         [_ev("D1", "Uses one specific, accurate, and correctly cited piece of evidence from a different source than part B", ["Cites a different source from the one used in part B and gives specific and relevant evidence from it that supports the claim"], ["Source 2: 7.6 hours versus 6.4 hours of sleep", "Source 3: mean GPA rose from 2.90 to 3.02", "Source 1: 85% versus 71% (if Source 2 or 3 was used in part B)"], ["uses the same source as part B", "gives evidence with no citation", "gives evidence that is not relevant to the claim"])])
    e = ("Circadian rhythm: during adolescence the body's internal clock shifts so that teenagers tend to feel sleepy later at night and wake later in the morning, so an early start conflicts with their rhythm and cuts their sleep, which a later start would reduce.",
         _expl_rows("E", ["Applies a different psychological perspective, theory, concept, or research finding from the course than the one used in part C, such as circadian rhythm, melatonin, sleep stages, or the effects of sleep deprivation on mood"], ["circadian rhythm shifts during adolescence", "melatonin is released later at night in teenagers", "the body's internal clock makes early wake times hard for teenagers"], ["explains how the evidence supports the claim: later starts matched with more hours of sleep, which supports changing the schedule", "links the evidence to the claim by showing that sleep amount is tied to start time"], ["more sleep went with later starts, which supports changing the schedule", "the sleep difference between the districts links start time to the amount of sleep, so the claim is supported"]))
    return _mk_frq("psf_ebq_school_start", "ebq", "1.5", ["1.5", "2.1"], "4.B", "Later school start times", intro, stim, _ebq_parts(q, ["1.5", "2.1"], claim, b, c, d, e), 45,
                   "Evidence-Based Question: propose a claim, support it with evidence from two sources, and explain with two different concepts", ["Propose a specific claim", "Cite specific evidence from one source and explain it with a course concept", "Cite evidence from a different source and explain it with a different concept"],
                   [("each source reports specific numbers or results that can be cited", "source text and table")], PATH_FRQ)


# ---- EBQ: 좋아요 수 숨기기 ----
def psf_ebq_like_counts(rng):
    q = "Should social media platforms hide the number of likes that posts receive?"
    intro = _sources([
        ("A field experiment with teenagers", "Researchers randomly assigned 100 teenagers to use a photo-sharing app for two weeks in one of two versions. In the Visible version (50 teenagers), like counts were shown under each post. In the Hidden version (50 teenagers), like counts were not shown. At the end of two weeks, each teenager rated how worried he or she felt about how others viewed his or her posts on a scale from 1 to 10. The mean rating was 6.8 in the Visible version and 5.2 in the Hidden version. The difference was statistically significant."),
        ("A survey of teenage app users", "Researchers surveyed 800 teenagers. Teenagers who said they check the like counts on their posts more than ten times a day reported lower self-esteem, and the correlation between how often teenagers check like counts and self-esteem was r = -0.31. The researchers noted that teenagers who volunteered for the survey may differ from teenagers who did not."),
        ("Interviews with teenagers about hidden counts", "Researchers interviewed 30 teenagers whose app had hidden like counts for one month. Of the 30, 19 said that they felt less pressure to post only popular photos. Eleven said that they still worried about what others thought of their posts and found other ways to compare themselves, such as counting comments. The researchers noted that teenagers who agreed to be interviewed may have had stronger opinions than others."),
    ])
    stim = tbl("Summary of the key results in the three sources", ["Source", "Type of study", "Key result"], [["1", "Experiment (100 teenagers)", "Mean worry rating (1-10): 6.8 (counts visible) vs 5.2 (counts hidden); statistically significant"], ["2", "Survey (800 teenagers)", "r = -0.31 between checking like counts and self-esteem"], ["3", "Interviews (30 teenagers)", "19 of 30 felt less pressure to post popular photos; 11 still worried and compared in other ways"]])
    claim = ["Platforms should hide like counts, because hiding them lowers teenagers' worry about how others view their posts.", "Platforms should hide like counts by default, because checking counts is linked to lower self-esteem and hiding them reduces worry.", "Platforms should let users hide like counts, but hiding alone is not enough, because some teenagers still compare themselves in other ways."]
    b = ("Source 1: teenagers who used the version with hidden like counts had a mean worry rating of 5.2, compared with 6.8 for teenagers who used the version with visible counts.",
         [_ev("B1", "Uses one specific, accurate, and correctly cited piece of evidence from one source", ["Cites one source (Source 1, 2, or 3) and gives specific and relevant evidence from it that supports the student's claim, such as a number or finding"], ["Source 1: 5.2 versus 6.8 on the worry rating", "Source 2: r = -0.31 between checking like counts and self-esteem", "Source 3: 19 of 30 felt less pressure to post popular photos"], ["gives evidence with no citation", "gives a vague statement such as 'the sources say likes are bad'", "gives evidence that is not relevant to the claim"])])
    c = ("Social comparison: when teenagers can see how many likes their posts get compared with others, they evaluate themselves against other people, which increases worry about how they are viewed; hiding the counts removes that comparison.",
         _expl_rows("C", ["Applies a psychological perspective, theory, concept, or research finding from the course, such as social comparison, self-esteem, social norms, or the need to belong, to explain how the evidence supports the claim"], ["social comparison: visible counts invite comparison with others", "self-esteem is affected by how one compares with others", "the need to belong makes teenagers concerned about approval"], ["explains how the evidence supports the claim: teenagers with hidden counts worried less, which supports hiding the counts", "links the evidence to the claim by showing how visible counts increase worry"], ["identifies the evidence without explaining how it relates to the claim", "describes the study without linking it to the claim"]))
    d = ("Source 3: 19 of the 30 interviewed teenagers said that they felt less pressure to post only popular photos when like counts were hidden.",
         [_ev("D1", "Uses one specific, accurate, and correctly cited piece of evidence from a different source than part B", ["Cites a different source from the one used in part B and gives specific and relevant evidence from it that supports the claim"], ["Source 3: 19 of 30 felt less pressure to post popular photos", "Source 2: r = -0.31 between checking like counts and self-esteem", "Source 1: 5.2 versus 6.8 (if Source 2 or 3 was used in part B)"], ["uses the same source as part B", "gives evidence with no citation", "gives evidence that is not relevant to the claim"])])
    e = ("Likes work as positive reinforcement delivered on an unpredictable schedule: teenagers keep posting and checking because an occasional large number of likes rewards the behavior, so removing the visible counts reduces the pressure to post only popular photos.",
         _expl_rows("E", ["Applies a different psychological perspective, theory, concept, or research finding from the course than the one used in part C, such as positive reinforcement, a variable-ratio schedule of reinforcement, operant conditioning, extrinsic motivation, or conformity"], ["positive reinforcement: likes reward posting", "variable-ratio schedule: unpredictable likes keep teenagers checking", "extrinsic motivation: teenagers post to earn approval from others"], ["explains how the evidence supports the claim: less pressure to post popular photos is a result of hiding the rewards", "links the evidence to the claim by showing how hiding counts changes teenagers' behavior"], ["identifies the evidence without explaining how it relates to the claim", "describes the evidence without linking it to the claim"]))
    return _mk_frq("psf_ebq_like_counts", "ebq", "4.1", ["4.1", "3.8"], "4.B", "Hiding like counts", intro, stim, _ebq_parts(q, ["4.1", "3.8"], claim, b, c, d, e), 45,
                   "Evidence-Based Question: propose a claim, support it with evidence from two sources, and explain with two different concepts", ["Propose a specific claim", "Cite specific evidence from one source and explain it with a course concept", "Cite evidence from a different source and explain it with a different concept"],
                   [("each source reports specific numbers or results that can be cited", "source text and table")], PATH_FRQ)


